// Shared by Starlight's real UI and the browser acceptance runner.
// Keep Starlight's defaults and give independently authored concepts a weight.
export const searchOptions = {
  ranking: { pageLength: 0.1, termFrequency: 0.1, termSaturation: 2, termSimilarity: 9, diacriticSimilarity: 0.8, metaWeights: { title: 5, search_terms: 8 } },
};

